import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
const read=p=>JSON.parse(fs.readFileSync(new URL('../'+p,import.meta.url)));const date='2026-09-28',ids=['saeon','leimma','runo','vox','memoria'];
test('September 28 publishes exactly five real deliveries, without converting gaps to research',()=>{const b=read('assets/citizen-work.json'),d=b.deliveries.filter(x=>x.executionId==='daily-20260928-root');assert.deepEqual(d.map(x=>x.citizenId).sort(),[...ids].sort());for(const x of d){assert.equal(x.review,null);assert.ok(fs.existsSync(new URL('../'+x.artifactPath,import.meta.url)));}for(const id of ids){const n=read(`research/${date}/${id}.json`);for(const l of ['zh','en','ko'])for(const k of ['title','lead','limitation','next'])assert.ok(n[k][l]);for(const a of n.attachments)assert.ok(fs.existsSync(new URL('../'+a.path,import.meta.url)));}});
test('September 28 energy edition splits conferences and exhibitions and keeps earlier archive',()=>{const e=read(`research/${date}/energy-observatory.json`);assert.equal(e.updatedAt,date);assert.equal(e.nextUpdate,'2026-10-05');assert.equal(e.editions.length,2);assert.equal(e.events.find(x=>x.id==='tbs26-workshop').end,'2026-10-12');assert.equal(e.events.find(x=>x.id==='tbs26-exhibition').start,'2026-10-13');assert.equal(e.events.find(x=>x.id==='tbs26-conference').kind,'conference');assert.equal(e.sources.find(x=>x.id==='iea-storage').checkedAt,'2026-09-22');assert.equal(read('research/2026-09-22/energy-observatory.json').updatedAt,'2026-09-22');});
test('new weekly candidates do not silently renew older candidates',()=>{const old=read(`research/${date}/weekly-learning-before.json`);assert.equal(old.updated,'2026-09-14');assert.ok(old.experiments.every(e=>e.deadline==='2026-09-21'));const w=read('assets/weekly-learning.json');if(w.updated===date){assert.equal(w.entries.length,3);assert.equal(w.experiments.length,3);assert.ok(w.previousExperimentEvaluation.every(e=>e.status==='expired_unverified'));for(const x of w.entries)for(const l of ['zh','en','ko'])assert.ok(x.localizedStatus[l]&&x.pattern[l]&&x.lesson[l]);}});
